SELECT assert_true(:catalog IN ('demo_dev', 'demo_test', 'demo_prod'), 'Invalid stage catalog');

SELECT assert_true(COUNT(*) = 0, 'Refusing to overwrite unowned demo tables')
FROM IDENTIFIER(:catalog || '.information_schema.tables')
WHERE table_schema = 'gold' AND table_name IN ('dim_product', 'dim_package', 'dim_channel', 'dim_region', 'dim_partner', 'fact_sales_monthly', 'fact_deliveries')
AND (comment IS NULL OR NOT startswith(comment, 'Managed by fabric-demo-platform demo automation'));

-- COMMAND ----------

CREATE OR REPLACE TABLE IDENTIFIER(:catalog || '.gold.dim_product')
USING DELTA COMMENT 'Managed by fabric-demo-platform demo automation: Illustrative beverage products.'
AS SELECT DISTINCT CAST(`sku` AS STRING) AS `sku`, CAST(`product_name` AS STRING) AS `product_name`, CAST(`product_line` AS STRING) AS `product_line`, CAST(`launch_year` AS INT) AS `launch_year`, CAST(`env_marker` AS STRING) AS `env_marker`
FROM IDENTIFIER(:catalog || '.silver.dim_product');
ALTER TABLE IDENTIFIER(:catalog || '.gold.dim_product') ALTER COLUMN `sku` COMMENT 'Product code; the number is a legacy code, not a package.';
ALTER TABLE IDENTIFIER(:catalog || '.gold.dim_product') ALTER COLUMN `product_name` COMMENT 'Product display name.';
ALTER TABLE IDENTIFIER(:catalog || '.gold.dim_product') ALTER COLUMN `product_line` COMMENT 'Still, Sparkling, Medium, Flavoured or Soft drink.';
ALTER TABLE IDENTIFIER(:catalog || '.gold.dim_product') ALTER COLUMN `launch_year` COMMENT 'Illustrative product launch year.';
ALTER TABLE IDENTIFIER(:catalog || '.gold.dim_product') ALTER COLUMN `env_marker` COMMENT 'Source environment: dev, test or prod.';

